// Selects the sources that are due to run.
//
// The whole due-source decision lives here, in n8n — the database stores
// next_run_at and priority but never acts on them.
//
// The sources table is small (dozens of rows), so it is fetched whole and
// filtered in memory rather than expressed as an OR query.

const all = $input.all().map(i => i.json);

// Settings rows and source rows arrive merged; separate them by shape.
const settingsRows = all.filter(r => typeof r.key === 'string' && 'value' in r);
const sources = all.filter(r => typeof r.base_url === 'string');

const setting = (key, fallback) => {
  const row = settingsRows.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fallback;
};

// Non-critical setting: a missing interval map falls back to the documented
// defaults rather than halting ingestion.
const intervals = setting('ingestion.priority_intervals', {
  '1': 60, '2': 180, '3': 360, '4': 720, '5': 1440,
});

const now = Date.now();
const due = [];

for (const s of sources) {
  // Belt and braces: the DB constraint already forbids an active source that
  // is not verified, but never crawl on the strength of one check.
  if (!s.active || s.config_status !== 'verified') continue;
  if (s.parser_type === 'unknown') continue;

  // A source in retry backoff waits until its next_retry_at passes (M10).
  if (s.next_retry_at && new Date(s.next_retry_at).getTime() > now) continue;

  const intervalMinutes = s.poll_interval_minutes
    ?? Number(intervals[String(s.priority)] ?? 360);

  const nextRun = s.next_run_at ? new Date(s.next_run_at).getTime() : 0;
  if (nextRun > now) continue;

  due.push({
    json: {
      source: s,
      interval_minutes: intervalMinutes,
      trigger_type: 'scheduled',
      dispatched_at: new Date(now).toISOString(),
    },
  });
}

return due;
